SELECT log_id, user_id, job_id, work_date, start_time, end_time, task_count, fatigue, estimated_income, status, settlement_status
FROM WORK_LOG
WHERE log_id = #{logId}

SELECT log_id, user_id, job_id, work_date, start_time, end_time, task_count, fatigue, estimated_income, status, settlement_status
FROM WORK_LOG
WHERE job_id = #{jobId}

SELECT log_id, user_id, job_id, work_date, start_time, end_time, task_count, fatigue, estimated_income, status, settlement_status
FROM WORK_LOG
WHERE user_id = #{userId}
  AND work_date = #{workDate}

SELECT log_id, user_id, job_id, work_date, start_time, end_time, task_count, fatigue, estimated_income, status, settlement_status
FROM WORK_LOG
WHERE user_id = #{userId}
  AND work_date BETWEEN #{startDate} AND #{endDate}

